if (root == nullptr) return;

// Recursively search for the node to delete
if (item < root->data) {
    avlDelete(root->left, item);
} else if (item > root->data) {
    avlDelete(root->right, item);
} else {
    // Node to delete found
    // Case 1: No children
    if (root->left == nullptr && root->right == nullptr) {
        delete root;
        root = nullptr;
    }
    // Case 2: One child (right child)
    else if (root->left == nullptr) {
        TreeNode* temp = root;
        root = root->right;
        delete temp;
    }
    // Case 3: One child (left child)
    else if (root->right == nullptr) {
        TreeNode* temp = root;
        root = root->left;
        delete temp;
    }
    // Case 4: Two children
    else {
        TreeNode* temp = root->right;
        while (temp->left != nullptr) {
            temp = temp->left;
        }
        root->data = temp->data;
        avlDelete(root->right, temp->data);
    }
}

// Update height
if (root != nullptr) {
    int leftHeight = (root->left == nullptr) ? -1 : root->left->height;
    int rightHeight = (root->right == nullptr) ? -1 : root->right->height;
    root->height = std::max(leftHeight, rightHeight) + 1;
}

// Balance the tree
if (root != nullptr) {
    int balanceFactor = leftHeight - rightHeight;
    if (balanceFactor > 1) {
        if (root->left->left != nullptr) {
            // Left-left case: rotate right
            TreeNode* temp = root->left;
            root->left = temp->right;
            temp->right = root;
            root = temp;
        } else {
            // Left-right case: rotate left-right
            TreeNode* temp = root->left->right;
            root->left->right = temp->left;
            temp->left = root->left;
            root->left = temp;
            avlDelete(root->left, item);
        }
    } else if (balanceFactor < -1) {
        if (root->right->right != nullptr) {
            // Right-right case: rotate left
            TreeNode* temp = root->right;
            root->right = temp->left;
            temp->left = root;
            root = temp;
        } else {
            // Right-left case: rotate right-left
            TreeNode* temp = root->right->left;
            root->right->left = temp->right;
            temp->right = root->right;
            root->right = temp;
            avlDelete(root->right, item);
        }
    }
}

